function icon(name, cls=''){ return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.dots}</svg>`; }
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(amount,currency='BDT')=>`${currency==='BDT'?'৳':currency+' '}${new Intl.NumberFormat('en-BD',{maximumFractionDigits:0}).format(Number(amount||0))}`;
const shortDate=(v)=>v?new Intl.DateTimeFormat('en-BD',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(v.replace(' ','T')+'Z')):'';
const productIcon=(key)=>({bike:'bike','bike-saver':'bike',car:'car',cng:'cng',parcel:'parcel',bolt:'bolt'})[key]||'car';
function toast(message,type=''){ const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;toastRegion.append(el);setTimeout(()=>el.remove(),3300); }
async function api(action,data=null,method='GET'){
  const opts={method,headers:{'Accept':'application/json'}};
  if(method==='POST'){opts.headers['Content-Type']='application/json';opts.headers['X-CSRF-Token']=state.boot?.csrf||'';opts.body=JSON.stringify(data||{});}
  const res=await fetch(`/api.php?action=${encodeURIComponent(action)}`,opts);
  let result;try{result=await res.json()}catch{throw new Error('The server returned an unreadable response.')}
  if(!res.ok)throw new Error(result.error||'Something went wrong.');
  if(result.csrf&&state.boot)state.boot.csrf=result.csrf;
  return result;
}
function setBusy(value){state.busy=value;document.querySelectorAll('button[type="submit"],.primary-button').forEach(b=>b.disabled=value)}
function nav(){return `<div class="bottom-nav-wrap"><nav class="bottom-nav" aria-label="Main navigation">${[['home','Home'],['services','Services'],['activity','Activity'],['account','Account']].map(([key,label])=>`<button class="nav-item ${state.tab===key?'active':''}" data-tab="${key}" aria-current="${state.tab===key?'page':'false'}">${icon(key)}<span>${label}</span></button>`).join('')}</nav></div>`}
function pageHeader(title,subtitle='',back=true){return `<header class="page-header">${back?`<button class="back-button" data-back aria-label="Go back">${icon('back')}</button>`:''}<div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div></header>`}
function appShell(content,opts={}){
 const user=state.boot?.user;const isAdmin=state.roleMode==='admin';
 return `<div class="app-shell"><header class="topbar"><a class="brand" href="#home" data-open="home"><span class="brand-mark">r</span><span>rideshare</span></a><div class="topbar-spacer"></div><button class="location-button" data-open="map">${icon('pin')}<span class="location-dot"></span><span>${esc(state.boot?.market?.city||'Bangladesh')}</span>${icon('chevrondown')}</button><button class="inbox-button" data-open="inbox" aria-label="Open inbox">${icon('bell')}</button></header><main class="app-main">${content}</main>${opts.hideNav?'':nav()}</div>`;
}
function renderAuth(){
 const signup=state.authMode==='signup';
 app.innerHTML=`<main class="auth-wrap"><section class="auth-card"><a class="brand"><span class="brand-mark">r</span><span>rideshare</span></a><h1>${signup?'Create your account':'Welcome back'}</h1><p>${signup?'A simpler way to move around Bangladesh.':'Sign in to request rides and manage your account.'}</p><form id="auth-form" class="form-stack"><div class="form-error" id="auth-error"></div>${signup?`<div class="field"><label for="full-name">Full name</label><input id="full-name" name="full_name" autocomplete="name" required maxlength="140" placeholder="Your name"></div>`:''}<div class="field"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" required placeholder="+880 1XXXXXXXXX"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="${signup?'10':'1'}" placeholder="${signup?'At least 10 characters':'Your password'}"></div><button class="primary-button" type="submit">${signup?'Create account':'Sign in'}</button></form><div class="auth-switch"><span>${signup?'Already have an account?':'New to RideShare?'}</span><button data-auth-mode="${signup?'login':'signup'}">${signup?'Sign in':'Create an account'}</button></div><p class="fine-print" style="margin:18px 0 0">Development access examples are documented in the project README. Use your own account in production.</p></section></main>`;
}
function iconForProduct(product){return icon(productIcon(product.icon_key),'');}
function renderHome(){
 const p=state.boot.places||[];const defaultPlace=state.route.origin||p.find(x=>x.place_key==='malibagh')||p[0];
 const cards=state.boot.home_cards||[];const products=state.boot.products||[];const promos=state.boot.promotions||[];
 return appShell(`<div class="hero-grid"><section class="hero-content"><div class="segmented" aria-label="Service type"><button class="active" type="button">${icon('car')} Rides</button><button data-open="services" type="button">${icon('parcel')} Delivery</button></div><section class="section"><button class="search-cta" data-open="planner">${icon('search','search-icon')}<strong>Where to?</strong><span class="later" data-schedule>${icon('calendar')}Later</span></button><button class="recent-card" data-open="planner"><span class="place-icon">${icon('pin')}</span><span><strong>${esc(defaultPlace?.label||'Choose pickup')}</strong><small>${esc(defaultPlace?.address||'Search a pickup location')}</small></span>${icon('chevron')}</button></section><section class="section"><div class="section-heading"><h2>Rides for you</h2><button class="subtle-link" data-open="services">View all</button></div><div class="service-chips">${products.filter(x=>x.service_type==='ride').slice(0,4).map(x=>`<button class="service-chip" data-product-shortcut="${x.id}"><span class="chip-icon">${iconForProduct(x)}</span><span>${esc(x.name)}</span></button>`).join('')}</div></section><section class="section"><div class="section-heading"><h2>Explore Bangladesh</h2><button class="subtle-link" data-open="map">See map</button></div><div class="horizontal-cards">${cards.map(c=>`<button class="destination-card" data-card-action="${esc(c.action_key)}"><strong>${esc(c.title)}</strong><small>${esc(c.subtitle)}</small></button>`).join('')}</div></section>${promos.length?`<section class="section"><div class="section-heading"><h2>For your next trip</h2><button class="subtle-link" data-open="inbox">Inbox</button></div>${promos.slice(0,1).map(p=>`<article class="promo-strip"><span class="promo-icon">${icon('star')}</span><span class="promo-copy"><strong>${esc(p.title)}</strong><small>${esc(p.subtitle)} · ${esc(p.badge)}</small></span>${icon('chevron')}</article>`).join('')}</section>`:''}</section><aside class="hero-side"><div class="mini-map" role="img" aria-label="Map preview of Bangladesh"><span class="country-outline"></span><span class="map-caption">${esc(state.boot.market?.city||'Dhaka')}, Bangladesh</span></div><p class="map-note">Live street maps open when you plan a ride.</p><section class="section"><div class="section-heading"><h2>Good to know</h2></div><article class="card"><strong style="font:700 14px Manrope">Simple distance pricing</strong><p>Ride estimates start at ৳100 per road kilometer. Your quote shows the route distance and rate before you book.</p><button class="text-button" data-open="planner">Plan a ride ${icon('arrow')}</button></article></section></aside></div>`);
}
function renderServices(){
 const products=state.boot.products||[];const delivery=products.filter(p=>p.service_type!=='ride');
 return appShell(`${pageHeader('Services','Choose how you want to get around or send something.',false)}<div class="section"><div class="section-heading"><h2>Rides</h2><span class="small-label">Dhaka service area</span></div><div class="card-grid">${products.filter(p=>p.service_type==='ride').map(p=>`<button class="card" style="text-align:left" data-product-shortcut="${p.id}"><span class="product-icon">${iconForProduct(p)}</span><h3 style="margin-top:13px">${esc(p.name)}</h3><p>${esc(p.description)}</p><span class="status-badge">${money(p.rate_per_km)} / km</span></button>`).join('')}</div></div><div class="section"><div class="section-heading"><h2>Parcel</h2></div>${delivery.length?delivery.map(p=>`<button class="card" data-open="delivery"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></button>`).join(''):`<div class="card"><div class="product-icon">${icon('parcel')}</div><h3 style="margin-top:12px">Send an item</h3><p>Parcel delivery is listed in the service catalogue, but delivery operations are not active yet.</p><button class="secondary-button" disabled>Coming later</button></div>`}</div><section class="section"><button class="card" style="width:100%;text-align:left" data-open="map"><h3>Explore the Bangladesh map</h3><p>Browse service areas and destinations. Ride requests are currently available only in configured zones.</p></button></section>`);
}
function tripCard(t){return `<article class="trip-row"><span class="prod-mini">${icon(productIcon((state.boot.products||[]).find(p=>p.name===t.product_name)?.icon_key||'car'))}</span><span><strong>${esc(t.destination_label||t.destination_address||'Trip')}</strong><small>${esc(t.origin_label||t.origin_address||'')} · ${esc(shortDate(t.created_at))} · ${Number(t.distance_km||0).toFixed(1)} km</small><small>${esc(t.product_name)} · <span class="status-badge ${esc(t.status)}">${esc(t.status.replaceAll('_',' '))}</span></small></span><span class="row-right"><strong>${money(t.fare_amount,t.currency)}</strong><button class="rebook" data-rebook="${esc(t.public_id)}">${icon('refresh')} Rebook</button></span></article>`;}
function renderActivity(){
 const trips=state.boot.trips||[];
 return appShell(`${pageHeader('Activity','Your recent and past trips.',false)}<section class="section"><div class="section-heading"><h2>Recent trips</h2><span class="small-label">${trips.length} shown</span></div>${trips.length?`<div class="trip-card">${trips.map(tripCard).join('')}</div>`:`<div class="empty-state"><span class="empty-icon">${icon('activity')}</span><strong>Your trips will show up here</strong><p>When you take a ride, you’ll find its route, fare and receipt in Activity.</p><button class="primary-button" style="max-width:230px;margin-top:18px" data-open="planner">Plan your first ride</button></div>`}</section>`);
}
function accountShortcut(label,iconName,target,badge=''){return `<button class="shortcut-card" data-open="${target}">${icon(iconName)}<span>${esc(label)}</span>${badge?'<i class="shortcut-dot"></i>':''}</button>`;}
function renderAccount(){
 const user=state.boot.user;const initials=(user.full_name||'R').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const roles=state.boot.roles||[];
 return appShell(`<section class="profile-head"><span class="avatar">${esc(initials)}</span><span><h1>${esc(user.full_name)}</h1><p>${esc(user.phone)} · ${state.boot.driver_profile?'Driver profile linked':'Rider account'}</p></span><button class="icon-button profile-edit" data-open="profile" aria-label="Edit profile">${icon('settings')}</button></section><div class="account-grid">${accountShortcut('Help','help','help')}${accountShortcut('Wallet','wallet','wallet')}${accountShortcut('Safety','shield','safety')}${accountShortcut('Inbox','inbox','inbox',(state.boot.support_cases||[]).length?'new':'')}</div>${(state.boot.promotions||[]).length?`<section class="section"><div class="section-heading"><h2>Offers for you</h2><button class="subtle-link" data-open="inbox">See all</button></div>${state.boot.promotions.slice(0,2).map(p=>`<article class="promo-strip" style="margin-bottom:9px"><span class="promo-icon">${icon('star')}</span><span class="promo-copy"><strong>${esc(p.title)}</strong><small>${esc(p.subtitle)} · ${esc(p.badge)}</small></span>${icon('chevron')}</article>`).join('')}</section>`:''}<section class="section"><div class="section-heading"><h2>Your account</h2></div><div class="list-row" data-open="family" role="button" tabindex="0"><span class="row-icon">${icon('family')}</span><span class="row-copy"><strong>Family and shared rides</strong><small>Manage people you ride with</small></span>${icon('chevron')}</div><div class="list-row" data-open="settings" role="button" tabindex="0"><span class="row-icon">${icon('settings')}</span><span class="row-copy"><strong>Settings</strong><small>Accessibility, language and trip preferences</small></span>${icon('chevron')}</div><div class="list-row" data-open="contacts" role="button" tabindex="0"><span class="row-icon">${icon('contact')}</span><span class="row-copy"><strong>Trusted contacts</strong><small>Manage trip-sharing contacts</small></span>${icon('chevron')}</div><div class="list-row" data-open="saved" role="button" tabindex="0"><span class="row-icon">${icon('pin')}</span><span class="row-copy"><strong>Saved places</strong><small>${(state.boot.saved_places||[]).length} saved addresses</small></span>${icon('chevron')}</div>${roles.includes('driver')?`<div class="list-row" data-open="driver" role="button" tabindex="0"><span class="row-icon">${icon('car')}</span><span class="row-copy"><strong>Driver app</strong><small>${esc(state.boot.driver_profile?.approval_status||'Application')}</small></span>${icon('chevron')}</div>`:`<div class="list-row" data-open="driver-apply" role="button" tabindex="0"><span class="row-icon">${icon('car')}</span><span class="row-copy"><strong>Earn with RideShare</strong><small>Apply to drive or deliver</small></span>${icon('chevron')}</div>`}${roles.includes('admin')?`<div class="list-row" data-open="admin" role="button" tabindex="0"><span class="row-icon">${icon('settings')}</span><span class="row-copy"><strong>Operations console</strong><small>Admin and marketplace tools</small></span>${icon('chevron')}</div>`:''}<div class="list-row" data-open="profile" role="button" tabindex="0"><span class="row-icon">${icon('account')}</span><span class="row-copy"><strong>Personal information</strong><small>Account and contact details</small></span>${icon('chevron')}</div><div class="list-row" data-logout><span class="row-icon">${icon('logout')}</span><span class="row-copy"><strong>Sign out</strong></span>${icon('chevron')}</div></section>`);
}
function plannerSuggestions(field){
 const text=(state.searchText||'').toLowerCase();const places=(state.boot.places||[]).filter(p=>!text||`${p.label} ${p.address} ${p.city}`.toLowerCase().includes(text)).slice(0,8);
 const saved=(state.boot.saved_places||[]).filter(p=>!text||`${p.label} ${p.address}`.toLowerCase().includes(text)).map(p=>({...p,category:'saved'}));
 return [...saved,...places].slice(0,10).map(p=>`<button class="suggestion-row" data-select-place="${esc(p.place_key||p.id)}" data-place-kind="${p.category==='saved'?'saved':'place'}">${icon(p.category==='saved'?'star':'clock')}<span><strong>${esc(p.label)}</strong><small>${esc(p.address)}</small></span>${icon('chevron')}</button>`).join('');
}
function renderPlanner(){
 const field=state.pickField;const val=state.route[field];const other=field==='origin'?'destination':'origin';const otherVal=state.route[other];
 return appShell(`${pageHeader('Plan your trip','Pickup and destination details.') }<div class="planner-layout"><section class="planner-panel"><div class="tabs"><button class="active" data-schedule-choice="now">${icon('clock')} Pick-up now</button><button data-schedule-choice="later" ${state.boot.services?.scheduling?'':'disabled'}>${icon('calendar')} ${state.boot.services?.scheduling?'Schedule':'Schedule unavailable'}</button><button data-who-choice>${icon('account')} ${esc(state.route.riderLabel||'For me')}</button></div><div class="route-points"><div class="route-inputs"><button class="route-field" data-pick-field="origin"><span class="route-mark"></span><span style="flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(state.route.origin?.label||'Choose pickup')}</span>${icon('search')}</button><button class="route-field" data-pick-field="destination"><span class="route-mark destination"></span><span style="flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(state.route.destination?.label||'Where to?')}</span>${icon('search')}</button>${(state.route.stops||[]).map((s,i)=>`<button class="route-field" data-edit-stop="${i}"><span class="route-mark destination"></span><span style="flex:1;text-align:left">${esc(s.label||`Stop ${i+1}`)}</span><button class="text-button" data-remove-stop="${i}" aria-label="Remove stop">${icon('close')}</button></button>`).join('')}</div><button class="add-stop" data-add-stop aria-label="Add a stop">${icon('plus')}</button></div><div id="field-suggestions" class="suggestion-list">${plannerSuggestions(field)}</div><div class="field" style="margin-top:15px"><label for="place-search">Search ${field==='origin'?'pickup':'destination'}</label><input id="place-search" class="search-input" autocomplete="off" placeholder="Search a place in Bangladesh" value="${esc(state.searchText)}"></div><div class="button-row" style="margin-top:12px"><button class="secondary-button" data-open="map-picker">${icon('map')} Set on map</button><button class="secondary-button" data-geolocate>${icon('pin')} Use my location</button></div><div class="notice" style="margin-top:14px">Map routes may use a routing provider to estimate road distance. Your app keeps the confirmed trip quote and locations in your account history.</div><div class="map-note">The booking map is centered on Bangladesh. Trips are available inside active service areas.</div>${state.route.scheduledFor?`<div class="field" style="margin-top:15px"><label for="schedule-at">Pickup date and time</label><input type="datetime-local" id="schedule-at" value="${esc(state.route.scheduledFor)}"></div>`:''}<button class="primary-button" style="margin-top:16px" data-view-quotes ${!state.route.origin||!state.route.destination?'disabled':''}>See ride options</button></section><section class="map-wrap"><div class="map-frame"><div id="planner-map" class="map-root" role="application" aria-label="Bangladesh map preview"></div></div><div class="map-note">© OpenStreetMap contributors · Search or move the pickup pin to refine your location.</div></section></div>`);
}
function renderMapPicker(){
 const point=state.route[state.pickField];
 return appShell(`${pageHeader(state.pickField==='origin'?'Choose pickup':'Choose destination','Move the marker or tap the map.') }<div class="map-wrap"><div class="map-frame" style="height:58dvh"><div id="pick-map" class="map-root" role="application" aria-label="Map of Bangladesh. Move the marker to choose a location."></div></div><div class="map-pin-hint"><span>${state.pickField==='origin'?'Pickup':'Destination'} · ${esc(point?.label||'Tap to drop a pin')}</span></div></div><div class="field" style="margin-top:13px"><label for="pin-label">Place name</label><input id="pin-label" value="${esc(point?.label||'Dropped pin')}" maxlength="180"></div><div class="field" style="margin-top:9px"><label for="pin-address">Address or landmark</label><input id="pin-address" value="${esc(point?.address||'Dhaka, Bangladesh')}" maxlength="240"></div><p class="map-note">Coordinates are saved to your trip only when you request a ride. Street tiles are provided by OpenStreetMap with attribution.</p><div class="map-picker-footer"><button class="primary-button" data-confirm-map>Confirm ${state.pickField==='origin'?'pickup':'destination'}</button></div>`);
}
function renderQuoteList(){
 if(!state.route.origin||!state.route.destination){state.view='planner';render();return ''}
 const selected=state.selectedQuote;const methods=state.boot.payments||[];
 return appShell(`${pageHeader('Choose a ride',`${esc(state.route.origin.label)} → ${esc(state.route.destination.label)}`)}<div class="planner-layout"><div class="map-wrap"><div class="map-frame"><div id="quote-map" class="map-root" aria-label="Ride map from pickup to destination"></div></div><div class="map-note">Route distance estimate · Bangladesh service area</div></div><section class="ride-sheet"><div class="section-heading"><h2>Ride options</h2><span class="small-label">${state.quotes.length?`${state.quotes[0].distance_km} km`:''}</span></div>${state.busy?`<div class="ride-list">${[1,2,3].map(()=>'<div class="skeleton"></div>').join('')}</div>`:state.quotes.length?`<div class="ride-list">${state.quotes.map(q=>{const p=state.boot.products.find(x=>Number(x.id)===Number(q.product_id));return `<button class="ride-option ${Number(selected?.quote_id)===Number(q.quote_id)?'selected':''}" data-select-quote="${q.quote_id}"><span class="product-icon">${iconForProduct(p||{})}</span><span class="ride-meta"><strong>${esc(q.product_name||p?.name||'Ride')}</strong><small>${p?.passenger_capacity||1} passenger${Number(p?.passenger_capacity)>1?'s':''} · ${esc(p?.description||'Ride across town')}</small></span><span class="ride-price">${money(q.fare_amount,q.currency)}<small class="fare-caption">${Number(q.distance_km).toFixed(1)} km × ${money(q.rate_per_km)} / km</small></span></button>`}).join('')}</div>`:`<div class="empty-state"><strong>Ride options are not available</strong><p>${esc(state.quoteError||'Try another pickup or destination.')}</p><button class="secondary-button" data-back>Change route</button></div>`}<div class="section" style="margin-top:18px"><div class="section-heading"><h2>Payment</h2><button class="subtle-link" data-open="wallet">Wallet</button></div><select id="payment-method" class="search-input" aria-label="Choose payment method">${methods.map(m=>`<option value="${esc(m.method_key)}" ${m.method_key===state.paymentKey?'selected':''} ${!Number(m.provider_ready)&&m.method_key!=='cash'?'disabled':''}>${esc(m.label)}${!Number(m.provider_ready)?' · not connected':''}</option>`).join('')}</select><small class="fare-caption">Payment options and connection status come from the service database.</small></div><button class="primary-button" data-request-ride ${!selected?'disabled':''}>${selected?`Request ride · ${money(selected.fare_amount,selected.currency)}`:'Select a ride'}</button><p class="fine-print">Distance × the rate stored for this ride option. Initial rate: ৳100 per road kilometer. No hidden base fee.</p></section></div>`);
}
function renderTrip(){
 const trip=(state.boot.trips||[]).find(t=>t.public_id===state.tripKey)||(state.boot.trips||[])[0];
 if(!trip)return appShell(`${pageHeader('Trip','Trip details') }<div class="empty-state"><strong>Trip not found</strong><p>Refresh your activity list and try again.</p></div>`);
 return appShell(`${pageHeader('Your ride',trip.status==='completed'?'Trip complete':trip.status==='cancelled'?'Trip canceled':'Your driver is on the way')}<div class="page-grid"><section><div class="map-frame"><div id="trip-map" class="map-root" aria-label="Trip map"></div></div><div class="map-note">Live location can be connected when the driver location provider is enabled.</div></section><section><div class="trip-state"><span class="state-mark"></span><span><strong class="status-badge ${esc(trip.status)}">${esc(trip.status.replaceAll('_',' '))}</strong><small>${esc(trip.status==='assigned'?'Your driver accepted the trip.':trip.status==='no_driver'?'Waiting for an available driver.':trip.status==='completed'?'Thanks for riding with us.':'Trip status is updated from the server.')}</small></span></div><article class="card" style="margin-top:12px"><h2>${esc(trip.product_name)}</h2><p>${esc(trip.driver_name||'Driver assignment pending')} ${trip.vehicle_label?`· ${esc(trip.vehicle_label)} · ${esc(trip.vehicle_plate||'')}`:''}</p><div class="list-row"><span class="row-icon">${icon('pin')}</span><span class="row-copy"><strong>${esc(trip.origin_label)}</strong><small>Pickup</small></span></div><div class="list-row"><span class="row-icon">${icon('map')}</span><span class="row-copy"><strong>${esc(trip.destination_label)}</strong><small>${Number(trip.distance_km).toFixed(1)} km · ${money(trip.rate_per_km)} / km</small></span></div><div class="list-row"><span class="row-icon">${icon('wallet')}</span><span class="row-copy"><strong>${money(trip.fare_amount,trip.currency)}</strong><small>${esc(trip.payment_method_key)} · final fare estimate</small></span></div></article><div class="account-grid" style="margin-top:12px">${accountShortcut('Share trip','send','safety')}${accountShortcut('Safety','shield','safety')}</div>${['requested','matching','assigned','driver_arriving','arrived'].includes(trip.status)?`<button class="danger-button" style="margin-top:12px" data-cancel-trip="${esc(trip.public_id)}">Cancel trip</button>`:''}<button class="secondary-button" style="margin-top:10px" data-open="help">Get help with this trip</button></section></div>`);
}
function renderWallet(){
 const methods=state.boot.payments||[];const trips=state.boot.trips||[];
 const profiles=state.boot.trip_profiles||[];
 return appShell(`${pageHeader('Wallet','Payment methods and trip profiles.') }<section class="wallet-balance"><small>RideShare Wallet</small><strong>Unavailable</strong><span class="small-label">A wallet balance is not configured</span></section><section class="section"><div class="section-heading"><h2>Payment methods</h2></div>${methods.map(m=>`<div class="list-row"><span class="row-icon">${icon(m.icon_key==='bkash'?'wallet':m.icon_key==='cash'?'card':'wallet')}</span><span class="row-copy"><strong>${esc(m.label)}</strong><small>${Number(m.provider_ready)?'Available for eligible trips':'Provider connection is not configured'}</small></span><span class="status-badge ${Number(m.provider_ready)?'completed':'pending'}">${Number(m.provider_ready)?'Ready':'Setup needed'}</span></div>`).join('')}<div class="notice warning" style="margin-top:12px">bKash stays unavailable until an approved gateway and verified payment callbacks are configured. Cash is available for local demo bookings.</div></section><section class="section"><div class="section-heading"><h2>Trip profiles</h2></div><div class="card">${profiles.map(p=>`<div class="list-row"><span class="row-icon">${icon('account')}</span><span class="row-copy"><strong>${esc(p.label)}</strong><small>${esc(p.profile_key)}</small></span><span class="status-badge ${p.profile_key==='personal'?'completed':'pending'}">${p.profile_key==='personal'?'Default':'Available'}</span></div>`).join('')||'<p class="helper">No trip profiles are configured.</p>'}<button class="secondary-button" style="margin-top:12px" data-open="family">Family and business profiles</button></div></section><section class="section"><div class="section-heading"><h2>Payment history</h2><button class="subtle-link" data-tab="activity">Trips</button></div>${trips.slice(0,5).length?trips.slice(0,5).map(t=>`<div class="list-row"><span class="row-icon">${icon('card')}</span><span class="row-copy"><strong>${esc(t.destination_label)}</strong><small>${esc(shortDate(t.created_at))} · ${esc(t.status)}</small></span><strong class="row-value">${money(t.fare_amount,t.currency)}</strong></div>`).join(''):`<p class="helper">Your completed trip charges will appear here.</p>`}</section>`);
}
function renderSafety(){
 const s=state.boot.safety||{};
 return appShell(`${pageHeader('Safety hub','Manage your trip safety preferences.') }<section class="card"><div class="section-heading"><h2>Safety preferences</h2>${icon('shield')}</div>${[['pin_verification','PIN verification','A trip PIN can help check you are getting into the right ride.'],['share_trip','Share trip location','Share trip progress with a trusted contact when you request.'],['ride_check','Trip check-in','Show a prompt if an unusual trip stop is detected.']].map(([key,title,desc])=>`<div class="toggle-row"><span class="toggle-copy"><strong>${title}</strong><small>${desc}</small></span><button class="switch" role="switch" aria-checked="${s[key]?'true':'false'}" data-safety-toggle="${key}" aria-label="${title}"></button></div>`).join('')}<div class="field" style="margin-top:17px"><label for="emergency-contacts">Emergency contact names</label><input id="emergency-contacts" value="${esc((s.emergency_contacts||[]).join(', '))}" placeholder="Add names separated by commas"></div><button class="primary-button" style="margin-top:12px" data-save-safety>Save safety preferences</button></section><section class="section"><div class="section-heading"><h2>Help if you need it</h2></div><div class="card"><p>If you are in immediate danger, contact your local emergency services directly. RideShare safety controls do not replace emergency responders.</p><button class="secondary-button" data-open="help">Open safety support</button></div></section>`);
}
function renderSettings(){
 const p=state.boot.preferences||{};
 return appShell(`${pageHeader('Settings','Choose how RideShare works for you.') }<section class="card"><div class="field"><label for="theme-setting">Appearance</label><select id="theme-setting"><option value="dark" ${p.theme==='dark'?'selected':''}>Dark</option><option value="light" ${p.theme==='light'?'selected':''}>Light</option><option value="system" ${p.theme==='system'?'selected':''}>Use device setting</option></select></div><div class="field" style="margin-top:15px"><label for="language-setting">Language</label><select id="language-setting"><option value="en-BD">English</option><option value="bn-BD" disabled>বাংলা · coming soon</option></select></div><div class="toggle-row"><span class="toggle-copy"><strong>Simple mode</strong><small>Larger, clearer booking controls</small></span><button class="switch" role="switch" aria-checked="${p.simple_mode?'true':'false'}" data-pref-toggle="simple_mode"></button></div><div class="toggle-row"><span class="toggle-copy"><strong>Scheduled rides</strong><small>Show the Later option when scheduling is available</small></span><button class="switch" role="switch" aria-checked="${p.scheduled_rides!==false?'true':'false'}" data-pref-toggle="scheduled_rides"></button></div><div class="field" style="margin-top:15px"><label for="auto-tip">Default tip percentage</label><input id="auto-tip" type="number" min="0" max="100" value="${Number(p.automatic_tip||0)}"></div><button class="primary-button" style="margin-top:14px" data-save-settings>Save preferences</button></section><section class="section"><div class="section-heading"><h2>Account</h2></div><div class="list-row" data-open="profile" role="button" tabindex="0"><span class="row-icon">${icon('account')}</span><span class="row-copy"><strong>Personal information</strong><small>Name, phone and email</small></span>${icon('chevron')}</div><div class="list-row" data-open="privacy" role="button" tabindex="0"><span class="row-icon">${icon('lock')}</span><span class="row-copy"><strong>Privacy and data</strong><small>Data use and account access</small></span>${icon('chevron')}</div><div class="list-row" data-open="privacy" role="button" tabindex="0"><span class="row-icon">${icon('bell')}</span><span class="row-copy"><strong>Communication preferences</strong><small>Manage trip and support notifications</small></span>${icon('chevron')}</div></section>`);
}
function renderProfile(){const u=state.boot.user;return appShell(`${pageHeader('Personal information','Your account information is saved securely.') }<form id="profile-form" class="card form-stack"><div class="field"><label for="profile-name">Full name</label><input id="profile-name" name="full_name" value="${esc(u.full_name)}" required maxlength="140"></div><div class="field"><label for="profile-phone">Phone number</label><input id="profile-phone" value="${esc(u.phone)}" disabled><small class="helper">Contact verification will be configured with the SMS provider.</small></div><div class="field"><label for="profile-email">Email address</label><input id="profile-email" name="email" type="email" value="${esc(u.email||'')}" placeholder="you@example.com"></div><button class="primary-button" type="submit">Save changes</button><p class="fine-print">Sensitive profile changes require verified account recovery and are recorded through the account service.</p></form>`);}
function renderSaved(){const places=state.boot.saved_places||[];return appShell(`${pageHeader('Saved places','Quickly choose places you use often.') }<div class="card"><div class="section-heading"><h2>Your saved addresses</h2><button class="text-button" data-open="save-place">${icon('plus')} Add</button></div>${places.length?places.map(p=>`<div class="list-row"><span class="row-icon">${icon('pin')}</span><span class="row-copy"><strong>${esc(p.label)}</strong><small>${esc(p.address)}</small></span><button class="text-button" data-delete-place="${p.id}" aria-label="Remove ${esc(p.label)}">${icon('close')}</button></div>`).join(''):`<div class="empty-state"><strong>No saved places yet</strong><p>Save a home, work or favorite address for faster booking.</p></div>`}</div>`);}
function renderSavePlace(){return appShell(`${pageHeader('Add a place','Choose a point on the Bangladesh map.') }<form id="saved-place-form" class="card form-stack"><div class="field"><label for="saved-label">Place label</label><input id="saved-label" required maxlength="80" placeholder="Home, Work, or another name"></div><div class="field"><label for="saved-address">Address</label><input id="saved-address" required maxlength="240" placeholder="Search or describe the address"></div><div class="field"><label for="saved-place-select">Match a known place</label><select id="saved-place-select"><option value="">Choose an address from database</option>${(state.boot.places||[]).map(p=>`<option value="${p.id}">${esc(p.label)} · ${esc(p.city)}</option>`).join('')}</select></div><button class="secondary-button" type="button" data-open="map-picker">Choose coordinates on map</button><p class="helper">${state.route.savedPoint?`Selected map point: ${state.route.savedPoint.lat.toFixed(5)}, ${state.route.savedPoint.lng.toFixed(5)}`:'Coordinates are needed to save a location.'}</p><button class="primary-button" type="submit">Save place</button></form>`);}
function renderHelp(){const cases=state.boot.support_cases||[];return appShell(`${pageHeader('Help','What can we help you with?') }${cases.length?`<section class="section"><div class="section-heading"><h2>Recent support</h2></div>${cases.map(c=>`<button class="list-row" style="width:100%;text-align:left" data-open-case="${esc(c.public_id)}"><span class="row-icon">${icon('help')}</span><span class="row-copy"><strong>${esc(c.subject)}</strong><small>${esc(c.topic)} · ${esc(c.status.replaceAll('_',' '))} · ${esc(shortDate(c.updated_at))}</small></span>${icon('chevron')}</button>`).join('')}</section>`:''}<section class="section"><div class="section-heading"><h2>Select a trip</h2><button class="subtle-link" data-tab="activity">View all</button></div>${(state.boot.trips||[]).slice(0,3).map(t=>`<button class="list-row" style="width:100%;text-align:left" data-help-trip="${esc(t.public_id)}"><span class="row-icon">${icon('car')}</span><span class="row-copy"><strong>${esc(t.destination_label)}</strong><small>${esc(shortDate(t.created_at))} · ${money(t.fare_amount,t.currency)}</small></span>${icon('chevron')}</button>`).join('')||'<p class="helper">Trip-specific help will appear here after your first ride.</p>'}</section><section class="section"><div class="section-heading"><h2>Browse help topics</h2></div><div class="card-grid">${(state.boot.support_topics||[]).map(t=>`<button class="shortcut-card" data-support-topic="${t.id}">${icon(t.category==='Safety'?'shield':'help')}<span>${esc(t.title)}</span>${icon('chevron')}</button>`).join('')}</div></section><section class="section"><button class="secondary-button" data-support-topic="${state.boot.support_topics?.find(t=>t.topic_key==='other')?.id||''}">Start a support conversation</button></section>`);}
function renderSupportForm(){const topic=(state.boot.support_topics||[]).find(t=>String(t.id)===String(state.supportTopic));return appShell(`${pageHeader(topic?.title||'Contact support','Send a message to the RideShare support queue.') }<form id="support-form" class="card form-stack"><div class="field"><label for="support-topic">Topic</label><select id="support-topic" required>${(state.boot.support_topics||[]).map(t=>`<option value="${t.id}" ${String(t.id)===String(state.supportTopic)?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div><div class="field"><label for="support-trip">Related trip (optional)</label><select id="support-trip"><option value="">General question</option>${(state.boot.trips||[]).map(t=>`<option value="${esc(t.public_id)}">${esc(t.destination_label)} · ${esc(shortDate(t.created_at))}</option>`).join('')}</select></div><div class="field"><label for="support-subject">Subject</label><input id="support-subject" maxlength="180" required placeholder="Briefly describe the issue"></div><div class="field"><label for="support-message">Message</label><textarea id="support-message" maxlength="3000" required placeholder="Tell us what happened and what you need help with."></textarea></div><button class="primary-button" type="submit">Send to support</button><p class="fine-print">Your message and case status are stored in your RideShare account. This is not an emergency service.</p></form>`);}
function renderInbox(){const promos=state.boot.promotions||[];const cases=state.boot.support_cases||[];return appShell(`${pageHeader('Inbox','Offers and account messages.') }<div class="tabs" style="margin-bottom:16px">${['all','offers','support','updates','priority'].map(f=>`<button class="${state.inboxFilter===f?'active':''}" data-inbox-filter="${f}">${f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>${['all','offers','updates','priority'].includes(state.inboxFilter)&&promos.length?`<section class="section"><div class="section-heading"><h2>Offers</h2></div>${promos.map(p=>`<article class="promo-strip" style="margin-bottom:10px"><span class="promo-icon">${icon('star')}</span><span class="promo-copy"><strong>${esc(p.title)}</strong><small>${esc(p.subtitle)} · ${esc(p.badge)}</small></span><button class="text-button" data-open="planner">Book</button></article>`).join('')}</section>`:''}${['all','support','priority'].includes(state.inboxFilter)?`<section class="section"><div class="section-heading"><h2>Support updates</h2></div>${cases.length?cases.map(c=>`<button class="list-row" style="width:100%;text-align:left" data-open-case="${esc(c.public_id)}"><span class="row-icon">${icon('inbox')}</span><span class="row-copy"><strong>${esc(c.subject)}</strong><small>${esc(c.status.replaceAll('_',' '))} · ${esc(shortDate(c.updated_at))}</small></span>${icon('chevron')}</button>`).join(''):`<div class="empty-state"><strong>Nothing important right now</strong><p>Support updates and account notices will appear here.</p></div>`}</section>`:''}`);}
function renderDriver(){const dp=state.boot.driver_profile;const trips=state.boot.driver_trips||[];if(!dp)return appShell(`${pageHeader('Driver application','Earn by providing rides.') }<form id="driver-apply-form" class="card form-stack"><div class="notice">Submit your vehicle details to create a driver application. Your account stays in review until the operations team approves it.</div><div class="field"><label for="vehicle-model">Vehicle make and model</label><input id="vehicle-model" required maxlength="120" placeholder="Example: Toyota Axio"></div><div class="field"><label for="vehicle-plate">Vehicle registration number</label><input id="vehicle-plate" required maxlength="40" placeholder="DHAKA-METRO-GA-0000"></div><button class="primary-button" type="submit">Submit driver application</button></form>`);
 const active=dp.online_status==='online';return appShell(`${pageHeader('Driver app',dp.approval_status==='approved'?'Your driver workspace.':`Application ${dp.approval_status}`) }${dp.approval_status!=='approved'?`<div class="onboard-banner"><strong>Driver profile ${esc(dp.approval_status)}</strong><small>Trip access opens when your identity, vehicle and local requirements are approved by operations.</small></div>`:`<div class="driver-live"><span class="location-dot"></span><span class="row-copy"><strong>${active?'You are online':'You are offline'}</strong><small>${active?'Eligible to receive a trip request':'Turn online when you are ready to drive'}</small></span><button class="switch" role="switch" aria-checked="${active}" data-driver-online aria-label="Go ${active?'offline':'online'}"></button></div>`}<section class="section"><div class="stat-grid"><article class="stat-card"><small>Today’s earnings</small><strong>${money(state.boot.driver_earnings?.total||0)}</strong></article><article class="stat-card"><small>Completed rides</small><strong>${Number(state.boot.driver_earnings?.trips||0)}</strong></article><article class="stat-card"><small>Driver rating</small><strong>${Number(dp.rating||5).toFixed(2)}</strong></article><article class="stat-card"><small>Vehicle</small><strong style="font-size:15px">${esc(dp.vehicle_label||'Not added')}</strong></article></div></section><section class="section"><div class="section-heading"><h2>Current trip</h2><span class="small-label">From database</span></div>${trips.length?trips.map(t=>`<article class="card" style="margin-bottom:10px"><div class="section-heading"><h3>${esc(t.product_name)}</h3><span class="status-badge ${esc(t.status)}">${esc(t.status.replaceAll('_',' '))}</span></div><div class="list-row"><span class="row-icon">${icon('pin')}</span><span class="row-copy"><strong>${esc(t.origin_label)}</strong><small>Pickup</small></span></div><div class="list-row"><span class="row-icon">${icon('map')}</span><span class="row-copy"><strong>${esc(t.destination_label)}</strong><small>${money(t.fare_amount,t.currency)}</small></span></div><div class="button-row" style="margin-top:12px">${t.status==='assigned'||t.status==='driver_arriving'?`<button class="secondary-button" data-driver-action="arrived" data-trip="${esc(t.public_id)}">Arrived</button>`:''}${['assigned','driver_arriving','arrived'].includes(t.status)?`<button class="primary-button" data-driver-action="start" data-trip="${esc(t.public_id)}">Start trip</button>`:''}${t.status==='in_progress'?`<button class="primary-button" data-driver-action="complete" data-trip="${esc(t.public_id)}">Complete trip</button>`:''}</div></article>`).join(''):`<div class="empty-state"><span class="empty-icon">${icon('car')}</span><strong>No active trip</strong><p>Accepted rides will appear here with pickup and trip actions.</p></div>`}</section><section class="section"><div class="section-heading"><h2>Driver tools</h2></div><div class="account-grid">${accountShortcut('Earnings','wallet','driver-earnings')}${accountShortcut('Safety','shield','safety')}${accountShortcut('Support','help','help')}${accountShortcut('Profile','account','profile')}</div></section>`);
}
function renderAdmin(){const stats=state.boot.admin_stats||{};const products=state.boot.pricing||[];const drivers=state.boot.admin_drivers||[];const trips=state.boot.admin_trips||[];return appShell(`${pageHeader('Operations','Marketplace health and controls.') }<div class="stat-grid">${[['Active trips',stats.active_trips],['Open support',stats.open_cases],['Online drivers',stats.online_drivers],['Today’s requests',stats.today_rides]].map(([label,n])=>`<article class="stat-card"><small>${label}</small><strong>${Number(n||0)}</strong></article>`).join('')}</div><div class="admin-layout"><section class="section"><div class="section-heading"><h2>Pricing rules</h2><span class="small-label">BDT / road km</span></div><div class="card">${products.map(p=>`<form class="admin-rate-form list-row" data-product-id="${p.id}"><span class="row-copy"><strong>${esc(p.name)}</strong><small>Current rate · ${money(p.rate_per_km)} / km</small></span><input class="rate-input" type="number" min="1" step="1" value="${Number(p.rate_per_km)}" aria-label="${esc(p.name)} price per kilometer"><button class="text-button" type="submit">Save</button></form>`).join('')}<p class="fine-print">Changes create an effective-dated pricing rule and an audit record. Add a reason for every rate change.</p></div></section><section class="section"><div class="section-heading"><h2>Driver review</h2><span class="small-label">${drivers.length} profiles</span></div><div class="card">${drivers.length?drivers.map(d=>`<div class="list-row"><span class="row-copy"><strong>${esc(d.full_name)}</strong><small>${esc(d.vehicle_label||'Vehicle pending')} · ${esc(d.vehicle_plate||'')}</small></span><span class="status-badge ${esc(d.approval_status)}">${esc(d.approval_status)}</span>${d.approval_status!=='approved'?`<button class="text-button" data-approve-driver="${d.id}">Approve</button>`:''}</div>`).join(''):'<p class="helper">Driver applications appear here when submitted.</p>'}</div></section></div><section class="section"><div class="section-heading"><h2>Recent trips</h2><span class="small-label">Rider and driver records</span></div><div class="card admin-table-wrap"><table class="admin-table"><thead><tr><th>Trip</th><th>Rider</th><th>Driver</th><th>Route</th><th>Fare</th><th>Status</th></tr></thead><tbody>${trips.map(t=>`<tr><td>${esc(t.public_id)}</td><td>${esc(t.rider_name)}</td><td>${esc(t.driver_name||'Unassigned')}</td><td>${esc(t.origin_label)} → ${esc(t.destination_label)}</td><td>${money(t.fare_amount,t.currency)}</td><td><span class="status-badge ${esc(t.status)}">${esc(t.status.replaceAll('_',' '))}</span></td></tr>`).join('')||'<tr><td colspan="6">No trips to show.</td></tr>'}</tbody></table></div></section>`);
}
function renderFamily(){return appShell(`${pageHeader('Family and shared rides','Manage who can ride with your account.') }<div class="card"><span class="product-icon">${icon('family')}</span><h2 style="margin-top:14px">Shared profiles are not connected yet</h2><p>This area is reserved for invited riders, trip permissions and shared payment rules. When enabled, member permissions and relationships will be stored in MySQL.</p><button class="secondary-button" disabled>Invite a family member</button></div>`);}
function renderPrivacy(){return appShell(`${pageHeader('Privacy and data','Control the information connected to your account.') }<div class="card"><h2>Your data in RideShare</h2><p>Profile, saved addresses, trip requests, quotes, preferences and support messages are stored in your RideShare account database. Precise location is used when you choose it for a trip or map action.</p><div class="list-row"><span class="row-icon">${icon('lock')}</span><span class="row-copy"><strong>Database-backed account</strong><small>Access is limited to your account and approved staff roles.</small></span></div><button class="secondary-button" style="margin-top:12px" data-open="help">Request a data copy or deletion</button></div>`);}
function renderContacts(){return appShell(`${pageHeader('Trusted contacts','Emergency and trip-sharing contacts.') }<div class="card"><p>Contact import is disabled until the app can request consent and store the selected contacts securely.</p><button class="secondary-button" data-open="safety">Manage safety contact names</button></div>`);}
function renderDriverEarnings(){return appShell(`${pageHeader('Earnings','Driver earnings are based on completed trips.') }<div class="stat-grid"><article class="stat-card"><small>Today</small><strong>${money(state.boot.driver_earnings?.total||0)}</strong></article><article class="stat-card"><small>Completed</small><strong>${Number(state.boot.driver_earnings?.trips||0)} rides</strong></article></div><section class="section"><div class="notice warning">Cash-out and provider payouts are not connected. This view currently reports completed-trip fares stored in the database.</div></section>${(state.boot.driver_trips||[]).map(t=>`<div class="list-row"><span class="row-icon">${icon('wallet')}</span><span class="row-copy"><strong>${esc(t.destination_label)}</strong><small>${esc(shortDate(t.created_at))} · ${esc(t.status)}</small></span><strong class="row-value">${money(t.fare_amount,t.currency)}</strong></div>`).join('')}`);}
function render(){
 if(!state.boot?.authenticated){renderAuth();return}
 const renderers={home:renderHome,services:renderServices,activity:renderActivity,account:renderAccount,planner:renderPlanner,'map-picker':renderMapPicker,quotes:renderQuoteList,trip:renderTrip,wallet:renderWallet,safety:renderSafety,settings:renderSettings,profile:renderProfile,saved:renderSaved,'save-place':renderSavePlace,help:renderHelp,'support-form':renderSupportForm,inbox:renderInbox,driver:renderDriver,admin:renderAdmin,family:renderFamily,privacy:renderPrivacy,contacts:renderContacts,'driver-earnings':renderDriverEarnings,map:()=>appShell(`${pageHeader('Bangladesh map','Map coverage and configured ride zones.') }<div class="map-frame" style="height:66dvh"><div id="country-map" class="map-root" aria-label="Map of Bangladesh"></div></div><p class="map-note">© OpenStreetMap contributors. Dhaka is the initial ride service zone; the other cities are available for map browsing.</p>`),delivery:()=>appShell(`${pageHeader('Parcel delivery','Send or receive an item.') }<div class="card"><span class="product-icon">${icon('parcel')}</span><h2 style="margin-top:14px">Parcel operations are not active</h2><p>The customer app keeps this service separate from passenger rides. Delivery can be enabled after driver workflows, item rules and delivery pricing are configured.</p></div>`)};
 const content=(renderers[state.view]||renderHome)();
 if(content!==undefined)app.innerHTML=content;
 requestAnimationFrame(()=>mountVisibleMap());
}
function updateTab(tab){state.tab=tab;state.view=tab;render();window.scrollTo({top:0,behavior:'smooth'});}
function openPlanner(){state.view='planner';state.tab='home';state.searchText='';if(!state.route.origin){const p=state.boot.places.find(x=>x.place_key==='malibagh')||state.boot.places[0];if(p)state.route.origin={label:p.label,address:p.address,lat:Number(p.lat),lng:Number(p.lng)};}render();}
async function loadQuotes(){
 if(!state.route.origin||!state.route.destination){toast('Choose a pickup and destination first.','error');return}
 state.view='quotes';state.quotes=[];state.selectedQuote=null;state.busy=true;render();
 try{
   const products=state.boot.products.filter(p=>p.service_type==='ride');
   const responses=await Promise.all(products.map(async p=>({product_id:p.id,product_name:p.name,...await api('quote',{product_id:p.id,origin:state.route.origin,destination:state.route.destination},'POST')})));
   state.quotes=responses;state.selectedQuote=responses[0]||null;state.quoteError='';
 }catch(e){state.quoteError=e.message;toast(e.message,'error')}
 finally{state.busy=false;render()}
}
function mountVisibleMap(){
 const mapEl=document.querySelector('#planner-map,#pick-map,#quote-map,#trip-map,#country-map');if(!mapEl)return;
 if(!window.L){mapEl.innerHTML='<div class="mini-map" style="height:100%"><span class="country-outline"></span><span class="map-caption">Bangladesh · Dhaka service area</span></div>';return}
 if(state.map){try{state.map.remove()}catch{}state.map=null;state.marker=null;}
 const id=mapEl.id;const cfg=state.boot.map||{};const center=[Number(cfg.center_lat||23.8103),Number(cfg.center_lng||90.4125)];const zoom=id==='country-map'?Number(cfg.country_zoom||7):Number(cfg.default_zoom||12);
 const map=window.L.map(mapEl,{zoomControl:id!=='pick-map',scrollWheelZoom:false}).setView(center,zoom);state.map=map;
 const tileUrl=window.RIDESHARE_TILE_URL||'https://tile.openstreetmap.org/{z}/{x}/{y}.png';
 window.L.tileLayer(tileUrl,{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors</a>'}).addTo(map);
 const origin=state.route.origin,dest=state.route.destination;
 if(origin){window.L.marker([origin.lat,origin.lng],{draggable:id==='pick-map'&&state.pickField==='origin'}).addTo(map).bindPopup('Pickup');}
 if(dest){window.L.marker([dest.lat,dest.lng],{draggable:id==='pick-map'&&state.pickField==='destination'}).addTo(map).bindPopup('Destination');}
 if(id==='pick-map'){
   const active=state.route[state.pickField];
   if(active){state.marker=window.L.marker([active.lat,active.lng],{draggable:true}).addTo(map);state.marker.on('dragend',()=>{const ll=state.marker.getLatLng();setPin(ll.lat,ll.lng);});}
   map.on('click',ev=>{if(state.marker)state.marker.setLatLng(ev.latlng);else state.marker=window.L.marker(ev.latlng,{draggable:true}).addTo(map);setPin(ev.latlng.lat,ev.latlng.lng);});
 }
 if(origin&&dest&&id!=='pick-map'){
   const line=window.L.polyline([[origin.lat,origin.lng],[dest.lat,dest.lng]],{color:'#c8f36a',weight:4,dashArray:'7 7',opacity:.8}).addTo(map);map.fitBounds(line.getBounds().pad(.35));
 }
 if(origin&&!dest&&id==='planner-map')map.setView([origin.lat,origin.lng],13);
 setTimeout(()=>map.invalidateSize(),120);
}
function setPin(lat,lng){state.route[state.pickField]={...(state.route[state.pickField]||{}),label:'Dropped pin',address:'Selected location in Bangladesh',lat:Number(lat),lng:Number(lng)};const hint=document.querySelector('.map-pin-hint span');if(hint)hint.textContent=`${state.pickField==='origin'?'Pickup':'Destination'} · ${lat.toFixed(5)}, ${lng.toFixed(5)}`;}
function choosePlace(key,kind){let p;if(kind==='saved')p=(state.boot.saved_places||[]).find(x=>String(x.id)===String(key));else p=(state.boot.places||[]).find(x=>String(x.place_key)===String(key));if(!p)return;state.route[state.pickField]={label:p.label,address:p.address,lat:Number(p.lat),lng:Number(p.lng)};state.searchText='';render();}
function routeFromTrip(t){state.route={origin:{label:t.origin_label,address:t.origin_address,lat:Number(t.origin_lat),lng:Number(t.origin_lng)},destination:{label:t.destination_label,address:t.destination_address,lat:Number(t.destination_lat),lng:Number(t.destination_lng)},stops:[]};openPlanner();}
async function refresh(){const b=await api('bootstrap');state.boot=b;document.documentElement.dataset.theme=b.preferences?.theme||'dark';if(!b.authenticated){state.view='home';state.tab='home'}else{if(b.roles.includes('driver')&&!b.roles.includes('rider'))state.view='driver';if(b.roles.includes('admin')&&!b.roles.includes('rider'))state.view='admin'}render();}
function closeToView(view){state.view=view;render();window.scrollTo({top:0,behavior:'smooth'});}

document.addEventListener('click',async e=>{
 const tab=e.target.closest('[data-tab]');if(tab){updateTab(tab.dataset.tab);return}
 const auth=e.target.closest('[data-auth-mode]');if(auth){state.authMode=auth.dataset.authMode;render();return}
 if(e.target.closest('[data-open="planner"]')||e.target.closest('[data-schedule]')){openPlanner();return}
 const go=e.target.closest('[data-open]');if(go){const v=go.dataset.open;if(v==='driver'&&!state.boot.roles.includes('driver')){toast('Submit a driver application first.');return}if(v==='admin'&&!state.boot.roles.includes('admin')){toast('Administrator access is required.','error');return}closeToView(v);return}
 if(e.target.closest('[data-back]')){if(state.view==='quotes')state.view='planner';else if(state.view==='map-picker')state.view=state.route.savedPoint?'save-place':'planner';else if(state.view==='trip')state.view='activity';else if(['support-form','privacy','contacts','saved','wallet','safety','settings','profile','family','driver-earnings'].includes(state.view))state.view='account';else state.view='home';render();return}
 const shortcut=e.target.closest('[data-product-shortcut]');if(shortcut){state.route.productId=Number(shortcut.dataset.productShortcut);openPlanner();return}
 if(e.target.closest('[data-view-quotes]')){const sched=document.querySelector('#schedule-at');if(sched)state.route.scheduledFor=sched.value;await loadQuotes();return}
 const picker=e.target.closest('[data-pick-field]');if(picker){state.pickField=picker.dataset.pickField;state.searchText='';render();return}
 const suggestion=e.target.closest('[data-select-place]');if(suggestion){choosePlace(suggestion.dataset.selectPlace,suggestion.dataset.placeKind);return}
 if(e.target.closest('[data-open="map-picker"]')){state.view='map-picker';render();return}
 if(e.target.closest('[data-open="map"]')){state.view='map';render();return}
 if(e.target.closest('[data-confirm-map]')){const active=state.route[state.pickField];if(!active){toast('Tap the map to set a location.','error');return}active.label=document.querySelector('#pin-label')?.value||active.label;active.address=document.querySelector('#pin-address')?.value||active.address;if(state.route.savedPoint){state.route.savedPoint={...active};state.view='save-place'}else state.view='planner';render();return}
 if(e.target.closest('[data-geolocate]')){if(!navigator.geolocation){toast('Location is not available in this browser.','error');return}navigator.geolocation.getCurrentPosition(pos=>{const {latitude,longitude}=pos.coords;if(latitude<20.5||latitude>26.8||longitude<88||longitude>93){toast('Your location is outside Bangladesh. Search for a place instead.','error');return}state.route.origin={label:'My location',address:'Current location',lat:latitude,lng:longitude};state.pickField='origin';render()},()=>toast('Location permission is off. You can search or set the pickup on the map.','error'),{enableHighAccuracy:true,timeout:10000});return}
 if(e.target.closest('[data-select-quote]')){const q=state.quotes.find(x=>String(x.quote_id)===String(e.target.closest('[data-select-quote]').dataset.selectQuote));state.selectedQuote=q;render();return}
 if(e.target.closest('[data-request-ride]')){const q=state.selectedQuote;if(!q)return;state.paymentKey=document.querySelector('#payment-method')?.value||'cash';setBusy(true);try{const result=await api('request-trip',{quote_id:q.quote_id,payment_method_key:state.paymentKey},'POST');state.tripKey=result.trip_id;toast(result.message);await refresh();state.view='trip';render()}catch(err){toast(err.message,'error')}finally{setBusy(false)}return}
 const cancel=e.target.closest('[data-cancel-trip]');if(cancel){if(!confirm('Cancel this trip? Any applicable cancellation fee will be shown by the service before the trip is canceled.'))return;try{await api('cancel-trip',{trip_id:cancel.dataset.cancelTrip},'POST');await refresh();state.view='trip';toast('Trip canceled.')}catch(err){toast(err.message,'error')}render();return}
 const rebook=e.target.closest('[data-rebook]');if(rebook){const t=state.boot.trips.find(x=>x.public_id===rebook.dataset.rebook);if(t){routeFromTrip(t)}return}
 const savePref=e.target.closest('[data-save-settings]');if(savePref){const prefs={...(state.boot.preferences||{}),theme:document.querySelector('#theme-setting')?.value||'dark',automatic_tip:Number(document.querySelector('#auto-tip')?.value||0)};document.querySelectorAll('[data-pref-toggle]').forEach(b=>prefs[b.dataset.prefToggle]=b.getAttribute('aria-checked')==='true');try{await api('save-preferences',{preferences:prefs,safety:state.boot.safety},'POST');await refresh();state.view='settings';toast('Settings saved.')}catch(err){toast(err.message,'error')}return}
 const saveSafety=e.target.closest('[data-save-safety]');if(saveSafety){const safety={...(state.boot.safety||{}),emergency_contacts:(document.querySelector('#emergency-contacts')?.value||'').split(',').map(x=>x.trim()).filter(Boolean)};document.querySelectorAll('[data-safety-toggle]').forEach(b=>safety[b.dataset.safetyToggle]=b.getAttribute('aria-checked')==='true');try{await api('save-preferences',{preferences:state.boot.preferences,safety},'POST');await refresh();state.view='safety';toast('Safety preferences saved.')}catch(err){toast(err.message,'error')}return}
 const toggle=e.target.closest('[data-safety-toggle],[data-pref-toggle]');if(toggle){toggle.setAttribute('aria-checked',toggle.getAttribute('aria-checked')==='true'?'false':'true');return}
 const online=e.target.closest('[data-driver-online]');if(online){const next=online.getAttribute('aria-checked')!=='true';try{await api('driver-status',{online:next},'POST');await refresh();state.view='driver';toast(next?'You are online.':'You are offline.')}catch(err){toast(err.message,'error')}return}
 const driverAction=e.target.closest('[data-driver-action]');if(driverAction){try{await api('driver-trip',{trip_id:driverAction.dataset.trip,next:driverAction.dataset.driverAction},'POST');await refresh();state.view='driver';toast('Trip status updated.')}catch(err){toast(err.message,'error')}return}
 const approve=e.target.closest('[data-approve-driver]');if(approve){const reason=prompt('Reason for approving this driver:');if(!reason)return;try{await api('admin-driver',{driver_id:Number(approve.dataset.approveDriver),status:'approved',reason},'POST');await refresh();state.view='admin';toast('Driver approved.')}catch(err){toast(err.message,'error')}return}
 const supportTopic=e.target.closest('[data-support-topic]');if(supportTopic){state.supportTopic=supportTopic.dataset.supportTopic;state.view='support-form';render();return}
 const helpTrip=e.target.closest('[data-help-trip]');if(helpTrip){state.helpTripId=helpTrip.dataset.helpTrip;state.supportTopic=state.boot.support_topics.find(t=>t.topic_key==='other')?.id;state.view='support-form';render();const s=document.querySelector('#support-trip');if(s)s.value=state.helpTripId;return}
 const openCase=e.target.closest('[data-open-case]');if(openCase){state.caseKey=openCase.dataset.openCase;state.view='case';renderCase();return}
 const filter=e.target.closest('[data-inbox-filter]');if(filter){state.inboxFilter=filter.dataset.inboxFilter;render();return}
 const remove=e.target.closest('[data-remove-stop]');if(remove){state.route.stops.splice(Number(remove.dataset.removeStop),1);render();return}
 if(e.target.closest('[data-add-stop]')){if(state.route.stops.length>=2){toast('Up to two extra stops are available in this demo.');return}state.route.stops.push({label:'New stop',address:'Dhaka, Bangladesh',lat:23.7806,lng:90.407});toast('Stop added. Choose it on the map or replace it from saved places.');render();return}
 const deletePlace=e.target.closest('[data-delete-place]');if(deletePlace){if(!confirm('Remove this saved place?'))return;try{await api('saved-place',{delete_id:Number(deletePlace.dataset.deletePlace)},'POST');await refresh();state.view='saved';toast('Saved place removed.')}catch(err){toast(err.message,'error')}return}
 if(e.target.closest('[data-logout]')){try{await api('logout',{},'POST');state.boot={authenticated:false};state.authMode='login';render()}catch(err){toast(err.message,'error')}return}
 if(e.target.closest('[data-card-action]')){const action=e.target.closest('[data-card-action]').dataset.cardAction;if(action==='map'){state.view='map';render()}else openPlanner();return}
 const when=e.target.closest('[data-schedule-choice]');if(when){if(when.dataset.scheduleChoice==='later'){if(!state.boot.services?.scheduling){toast('Scheduled rides are not enabled in this service area yet.');return}state.route.scheduledFor=new Date(Date.now()+3600000).toISOString().slice(0,16)}else state.route.scheduledFor=null;render();return}
 if(e.target.closest('[data-who-choice]')){const label=prompt('Who is riding? Enter “For me” or a guest name.',state.route.riderLabel||'For me');if(label){state.route.riderLabel=label;render()}return}
});

document.addEventListener('input',e=>{
 if(e.target.id==='place-search'){state.searchText=e.target.value;const box=document.querySelector('#field-suggestions');if(box)box.innerHTML=plannerSuggestions(state.pickField)}
});
document.addEventListener('change',e=>{
 if(e.target.id==='saved-place-select'&&e.target.value){const p=state.boot.places.find(x=>String(x.id)===String(e.target.value));if(p){state.route.savedPoint={lat:Number(p.lat),lng:Number(p.lng),label:p.label,address:p.address};document.querySelector('#saved-address').value=p.address}}
 if(e.target.id==='theme-setting'){document.documentElement.dataset.theme=e.target.value}
});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target;
 if(form.id==='auth-form'){
   const fd=new FormData(form);const body=Object.fromEntries(fd.entries());setBusy(true);
   try{const result=await api(state.authMode==='signup'?'signup':'login',body,'POST');state.boot.csrf=result.csrf;await refresh();toast(state.authMode==='signup'?'Account created.':'Welcome back.')}catch(err){const m=document.querySelector('#auth-error');if(m)m.textContent=err.message;else toast(err.message,'error')}finally{setBusy(false)}return;
 }
 if(form.id==='profile-form'){
   const fd=new FormData(form);try{await api('update-profile',Object.fromEntries(fd.entries()),'POST');await refresh();state.view='profile';toast('Profile updated.')}catch(err){toast(err.message,'error')}return;
 }
 if(form.id==='support-form'){
   const body={topic_id:Number(document.querySelector('#support-topic').value),trip_id:document.querySelector('#support-trip').value,subject:document.querySelector('#support-subject').value,message:document.querySelector('#support-message').value};try{const result=await api('support-case',body,'POST');await refresh();state.caseKey=result.case_id;state.view='case';renderCase();toast('Your support request was saved.')}catch(err){toast(err.message,'error')}return;
 }
 if(form.classList.contains('admin-rate-form')){
   const input=form.querySelector('.rate-input');const rate=Number(input.value);const reason=prompt('Reason for this pricing rule change:');if(!reason)return;
   try{await api('admin-rate',{product_id:Number(form.dataset.productId),rate_per_km:rate,reason},'POST');await refresh();state.view='admin';toast('New rate saved to MySQL with an audit entry.')}catch(err){toast(err.message,'error')}return;
 }
 if(form.id==='driver-apply-form'){
   try{await api('driver-apply',{vehicle_label:document.querySelector('#vehicle-model').value,vehicle_plate:document.querySelector('#vehicle-plate').value},'POST');await refresh();state.view='driver';toast('Driver application submitted for review.')}catch(err){toast(err.message,'error')}return;
 }
 if(form.id==='saved-place-form'){
   const p=state.route.savedPoint;const match=state.boot.places.find(x=>String(x.id)===String(document.querySelector('#saved-place-select').value));const lat=p?.lat??Number(match?.lat);const lng=p?.lng??Number(match?.lng);
   try{await api('saved-place',{label:document.querySelector('#saved-label').value,address:document.querySelector('#saved-address').value,lat,lng},'POST');await refresh();state.view='saved';toast('Place saved.')}catch(err){toast(err.message,'error')}return;
 }
});

async function renderCase(){
 const key=state.caseKey;app.innerHTML=appShell(`${pageHeader('Support conversation',`Case ${esc(key)}`)}<div class="card"><div id="case-messages"><div class="skeleton"></div></div><form id="reply-form" class="chat-composer"><input id="reply-message" maxlength="3000" placeholder="Write a reply" aria-label="Write a reply" required><button type="submit" aria-label="Send message">${icon('send')}</button></form></div>`);
 try{const response=await fetch(`/api.php?action=support-thread&case_id=${encodeURIComponent(key)}`,{headers:{'Accept':'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.error||'Conversation could not be loaded.');const el=document.querySelector('#case-messages');if(!el)return;el.innerHTML=`<div class="chat-date">${esc(result.status.replaceAll('_',' '))}</div>${result.messages.map(m=>`<div class="chat-bubble ${m.sender_type==='rider'?'mine':''}">${esc(m.body)}<div class="fare-caption">${m.sender_type==='rider'?'You':m.sender_type==='staff'?'Support':'RideShare'} · ${esc(shortDate(m.created_at))}</div></div>`).join('')||'<p class="helper">No messages yet.</p>'}`;}catch(err){const el=document.querySelector('#case-messages');if(el)el.innerHTML=`<div class="notice error">${esc(err.message)}</div>`}
}
document.addEventListener('submit',async e=>{
 if(e.target.id!=='reply-form')return;e.preventDefault();const msg=document.querySelector('#reply-message');try{await api('support-reply',{case_id:state.caseKey,message:msg.value},'POST');await refresh();state.view='case';await renderCase();toast('Message sent.')}catch(err){toast(err.message,'error')}
});

async function start(){
 try{state.boot=await api('bootstrap');document.documentElement.dataset.theme=state.boot.preferences?.theme||'dark';if(state.boot.authenticated){if(state.boot.roles.includes('driver')&&!state.boot.roles.includes('rider'))state.view='driver';if(state.boot.roles.includes('admin')&&!state.boot.roles.includes('rider'))state.view='admin';}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js').catch(()=>{});}
 catch(e){app.innerHTML=`<main class="auth-wrap"><section class="auth-card"><a class="brand"><span class="brand-mark">r</span><span>rideshare</span></a><h1>Can’t connect yet</h1><p>${esc(e.message)}</p><div class="notice warning">Start the PHP and MySQL services, import the database schema, and then refresh this page. No sample customer data is displayed when the database is unavailable.</div></section></main>`;}
}
start();
